import java.util.Scanner;

public class Main {
    static long mod;
    static final int MAX_N = 1 << 18;
    static Modint[] fact = new Modint[MAX_N];
    static Modint[] factinv = new Modint[MAX_N];
    static MP[] dp = new MP[501];
    static MP[][] dp2 = new MP[502][501];
    static boolean[] used = new boolean[501];

    // Modint class
    static class Modint {
        long n;

        Modint() { n = 0; }
        Modint(long m) {
            n = m % mod;
            if (n < 0) n += mod;
        }

        Modint add(Modint b) {
            long res = n + b.n;
            if (res >= mod) res -= mod;
            return new Modint(res);
        }

        Modint sub(Modint b) {
            long res = n - b.n;
            if (res < 0) res += mod;
            return new Modint(res);
        }

        Modint mul(Modint b) {
            return new Modint(n * b.n % mod);
        }

        Modint pow(long exp) {
            Modint res = new Modint(1);
            Modint base = new Modint(n);
            while (exp > 0) {
                if ((exp & 1) == 1) res = res.mul(base);
                base = base.mul(base);
                exp >>= 1;
            }
            return res;
        }

        Modint div(Modint b) {
            return mul(new Modint(inv(b.n, mod)));
        }

        @Override
        public String toString() {
            return Long.toString(n);
        }

        public boolean equals(Modint other) {
            return n == other.n;
        }
    }

    // Pair of Modints
    static class MP {
        Modint first, second;

        MP(Modint f, Modint s) {
            first = f;
            second = s;
        }

        MP add(MP other) {
            return new MP(first.add(other.first), second.add(other.second));
        }

        MP mul(MP other) {
            Modint a = first.mul(other.first);
            Modint b = second.mul(other.first).add(first.mul(other.second));
            return new MP(a, b);
        }
    }

    // Extended Euclidean algorithm: returns x such that a*x ≡ 1 mod m
    static long inv(long a, long m) {
        long m0 = m, x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            long q = a / m;
            long t = m;
            m = a % m;
            a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }

    static void init_f() {
        fact[0] = new Modint(1);
        for (int i = 0; i < MAX_N - 1; i++) {
            fact[i + 1] = fact[i].mul(new Modint(i + 1));
        }
        factinv[MAX_N - 1] = new Modint(1).div(fact[MAX_N - 1]);
        for (int i = MAX_N - 2; i >= 0; i--) {
            factinv[i] = factinv[i + 1].mul(new Modint(i + 1));
        }
    }

    static Modint comb(int a, int b) {
        if (a < 0 || b < 0 || a < b) return new Modint(0);
        return fact[a].mul(factinv[b]).mul(factinv[a - b]);
    }

    static void init() {
        init_f();
        dp[0] = new MP(new Modint(1), new Modint(0));
        dp[1] = new MP(new Modint(2), new Modint(0));
        for (int n = 2; n <= 500; n++) {
            dp[n] = new MP(new Modint(0), new Modint(0));
            for (int j = 0; j < n; j++) {
                Modint cnt = new Modint(n + 1);
                Modint sum = new Modint(0);
                for (int k = 0; k < n; k++) {
                    sum = sum.add(new Modint(Math.abs(j - k)));
                }
                MP cl = dp[j];
                MP cr = dp[n - 1 - j];
                MP x = cl.mul(cr);
                Modint combVal = comb(n - 1, j);
                x.first = x.first.mul(combVal);
                x.second = x.second.mul(combVal);
                x = x.mul(new MP(cnt, sum));
                dp[n] = dp[n].add(x);
            }
        }
    }

    static void solve() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextLong();
        init();
        for (int i = 0; i < 502; i++) {
            for (int j = 0; j < 501; j++) {
                dp2[i][j] = new MP(new Modint(0), new Modint(0));
            }
        }
        dp2[0][0] = new MP(new Modint(1), new Modint(0));
        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= i; k++) {
                for (int j = i; j < n; j++) {
                    int ni = j + 2;
                    if (ni > n) ni = n;
                    int nk = k + j - i + 1;
                    if (nk <= m) {
                        MP x = dp2[i][k].mul(dp[j - i + 1]);
                        Modint combnk = comb(nk, k);
                        x.first = x.first.mul(combnk);
                        x.second = x.second.mul(combnk);
                        dp2[ni][nk] = dp2[ni][nk].add(x);
                    }
                }
                dp2[i + 1][k] = dp2[i + 1][k].add(dp2[i][k]);
            }
        }
        Modint ans = dp2[n][m].second;
        System.out.println(ans);
    }

    public static void main(String[] args) {
        solve();
    }
}
